import{_ as r,a0 as s,w as l,s as m,ao as p,I as i,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用自動化時的五個常見錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"使用自動化時的五個常見錯誤 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用自動化時的五個常見錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用自動化時的五個常見錯誤 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220518 Five common mistakes when using automation","title":"使用自動化時的五個常見錯誤","tag":"202205","desc":""},"relativePath":"202205/20220518 Five common mistakes when using automation.md","filePath":"[post].md"}'),d={name:"202205/20220518 Five common mistakes when using automation.md"};function u(h,a,f,g,T,b){const e=s("Link");return l(),m("div",null,[a[15]||(a[15]=p('<h1 id="使用自動化時的五個常見錯誤" tabindex="-1">使用自動化時的五個常見錯誤 <a class="header-anchor" href="#使用自動化時的五個常見錯誤" aria-label="Permalink to “使用自動化時的五個常見錯誤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/31/151450ukwk98weqgefgowa.jpg" alt=""></p><p>隨着自動化擴展到涵蓋 IT 的更多方面，越來越多的管理員正在學習自動化技能並應用它們來減輕他們的工作量。自動化可以減輕重複性任務的負擔，併為基礎設施增加一定程度的一致性。但是，當 IT 工作人員部署自動化時，會出現可能對大大小小的基礎設施造成嚴重破壞的常見錯誤。在自動化部署中通常會出現五個常見錯誤。</p><h3 id="缺乏測試" tabindex="-1">缺乏測試 <a class="header-anchor" href="#缺乏測試" aria-label="Permalink to “缺乏測試”">​</a></h3><p>初學者常犯的錯誤是自動化腳本沒有經過全面測試。由於拼寫錯誤或邏輯錯誤，簡單的 shell 腳本可能會對服務器產生不利影響。將該錯誤乘以基礎架構中的服務器數量，你可能會遇到一大堆問題需要清理。在大規模部署之前始終測試你的自動化腳本。</p><h3 id="意外負載" tabindex="-1">意外負載 <a class="header-anchor" href="#意外負載" aria-label="Permalink to “意外負載”">​</a></h3><p>經常發生的第二個錯誤是沒有預測腳本可能對其他資源施加的系統負載。當目標是十幾個服務器時，運行從倉庫下載文件或安裝包的腳本可能沒問題。腳本通常在成百上千台服務器上運行。這種負載可以使支持服務停止或完全崩潰。不要忘記考慮端點影響或設置合理的併發率。</p><h3 id="離開腳本" tabindex="-1">離開腳本 <a class="header-anchor" href="#離開腳本" aria-label="Permalink to “離開腳本”">​</a></h3><p>自動化工具的一種用途是確保符合標準設置。自動化可以輕鬆確保組中的每台服務器都具有完全相同的設置。如果該組中的服務器需要根據該基線進行更改，同時管理員不瞭解合規標準，那麼可能會出現問題。安裝和啓用不需要和不想要的服務，從而導致可能的安全問題。</p><h3 id="缺乏文檔" tabindex="-1">缺乏文檔 <a class="header-anchor" href="#缺乏文檔" aria-label="Permalink to “缺乏文檔”">​</a></h3><p>管理員的一項固定職責應該是記錄他們的工作。由於合同到期、升職或定期員工流動，公司可能會在 IT 部門頻繁招聘新員工。公司內的工作組相互隔離也很常見。由於這些原因，重要的是記錄哪些自動化已經到位。與用户運行腳本不同，自動化可能會在創建它的人離開組之後繼續很長時間。管理員可能會發現自己在其基礎設施中面臨着來自未經檢查的自動化的奇怪行為。</p><h3 id="缺乏經驗" tabindex="-1">缺乏經驗 <a class="header-anchor" href="#缺乏經驗" aria-label="Permalink to “缺乏經驗”">​</a></h3><p>列表中的最後一個錯誤是管理員對他們正在自動化的系統不夠了解。管理員經常被僱用到他們沒有接受過足夠培訓且沒有人可以求教的職位上工作。自 COVID 以來，當公司努力填補空缺時，這一點尤其重要。然後管理員被迫處理他們沒有設置並且可能不完全理解的基礎設施。這可能會導致非常低效的腳本浪費資源或配置錯誤的服務器。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>越來越多的管理員正在學習自動化來幫助他們完成日常任務。因此，自動化正被應用於更多的技術領域。希望此列表將有助於防止新用户犯這些錯誤，並敦促經驗豐富的管理員重新評估他們的 IT 策略。自動化旨在減輕重複性任務的負擔，而不是為最終用户帶來更多工作。</p><hr>',16)),i("p",null,[a[1]||(a[1]=t("via: ",-1)),n(e,{href:"https://fedoramagazine.org/five-common-mistakes-when-using-automation/"},{default:o(()=>[...a[0]||(a[0]=[t("https://fedoramagazine.org/five-common-mistakes-when-using-automation/",-1)])]),_:1})]),i("p",null,[a[6]||(a[6]=t("作者：",-1)),n(e,{href:"https://fedoramagazine.org/author/gscarbor/"},{default:o(()=>[...a[2]||(a[2]=[t("Gary Scarborough",-1)])]),_:1}),a[7]||(a[7]=t(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...a[3]||(a[3]=[t("lujun9972",-1)])]),_:1}),a[8]||(a[8]=t(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...a[4]||(a[4]=[t("geekpi",-1)])]),_:1}),a[9]||(a[9]=t(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...a[5]||(a[5]=[t("wxy",-1)])]),_:1})]),i("p",null,[a[12]||(a[12]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[10]||(a[10]=[t("LCTT",-1)])]),_:1}),a[13]||(a[13]=t(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...a[11]||(a[11]=[t("Linux中國",-1)])]),_:1}),a[14]||(a[14]=t(" 榮譽推出",-1))])])}const w=r(d,[["render",u]]);export{C as __pageData,w as default};
